CREATE TABLE inbox(event_id VARCHAR(100) PRIMARY KEY,payment_id UUID NOT NULL UNIQUE,received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ledger(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id UUID NOT NULL,merchant_id VARCHAR(40) NOT NULL,account VARCHAR(40) NOT NULL,amount NUMERIC(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,UNIQUE(payment_id,account));
CREATE TABLE receipt_outbox(payment_id UUID PRIMARY KEY,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMPTZ);
CREATE INDEX receipt_pending ON receipt_outbox(next_attempt_at) WHERE completed_at IS NULL;
